"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3275],{53275:a=>{a.exports=JSON.parse('{"slug":"benzin-podorozhanie-2-1-rublya-import-oktyabr-2026","locale":"ru","title":"Минэнерго предложило поднять цены на бензин и дизель на 2,1 рубля за литр","description":"Минэнерго предложило разрешить нефтекомпаниям поднять цены на бензин и дизель на 2,1 рубля за литр, чтобы покрыть убытки от импорта топлива.","blocks":[{"id":"b001","kind":"paragraph","text":"В октябре вице-премьер Александр Новак направил премьеру Михаилу Мишустину обращение Минэнерго о ценах на топливо. В нём сказано, что импортный бензин и дизель на АЗС вертикально интегрированных нефтяных компаний продаются с убытком 13–18 рублей на литре, даже с учётом импортного демпфера. Министерство предложило два выхода. Первый: поднять цены на этих заправках на 2,1 рубля за литр. Второй: поднять на 1,6 рубля и включить в демпфер доставку топлива по железной дороге с Северо-Запада в центр страны."},{"id":"b002","kind":"paragraph","text":"Импорт понадобился, потому что своего бензина не хватает, Новак оценивает дефицит примерно в 5%. Россия ввозит топливо из Белоруссии и морем, в том числе из Индии. В октябре–декабре импорт бензина может составить около 620 тыс. тонн в месяц, это 16–18% поставок на внутренний рынок. Сам Новак называл долю около 10%. Импорт продлится как минимум до конца года."},{"id":"b003","kind":"paragraph","text":"Представим пекарню, которой не хватило своей муки. Недостающие мешки она покупает в магазине вдвое дороже, а хлеб продаёт по старой цене. Каждая буханка из покупной муки приносит убыток. Его покрывает кто-то из троих: пекарня, город доплатой или покупатель подорожавшим хлебом. В топливе цену такого покупного мешка называют импортной альтернативой. В сентябре импортный АИ-92 стоил 108 тыс. рублей за тонну, российский на бирже 70,17 тыс. В пересчёте на литр разница около 28 рублей."},{"id":"b004","kind":"paragraph","text":"Часть разницы покрывает импортный демпфер, доплата из бюджета. Но он не учитывает наценку, которую продавцы берут за санкционные риски, и доставку по России. Минфин против того, чтобы расширять доплату. Повышение на 2,1 рубля, по оценкам участников рынка, принесёт нефтепереработчикам около 12 млрд рублей дополнительной выручки в месяц без расходов бюджета. По оценке Минэнерго, с ним бензин на АЗС нефтяных компаний к концу года подорожает на 11%, или на 7,1 рубля за литр, летний дизель на 10,7%, или на 8,2 рубля. Это именно заправки нефтекомпаний: летом цены у них росли медленнее, чем у независимых."},{"id":"b005","kind":"paragraph","text":"Средний бензин по всем заправкам на 19 октября стоил 78,04 рубля за литр, с начала года он подорожал на 20,53% при общей инфляции 6,15%. Дизель стоил 86,58 рубля, плюс 13,38%. За последнюю неделю бензин подешевел на 0,69%. Очереди на заправках в большинстве регионов исчезли, сезонный спрос упал, и начали снижаться цены на независимых АЗС, которые летом дорожали быстрее остальных."},{"id":"b006","kind":"paragraph","text":"Решение правительство пока не приняло. Надбавка на АЗС нефтяных компаний сократит их убыток, но поднимет нижнюю планку цен. Если нефтекомпании поднимут и оптовые цены, дорожать придётся и независимым заправкам, которые покупают у них топливо. Подешевение нефти и импорта уменьшит разрыв, который нужно покрывать. Новые удары по НПЗ увеличат долю импорта, а с ней и убыток на каждом литре."},{"id":"b007","kind":"heading","text":"Подорожает ли бензин на 2,1 рубля за литр?"},{"id":"b008","kind":"paragraph","text":"Это предложение Минэнерго, решение правительство пока не приняло. Речь о ценах на АЗС вертикально интегрированных нефтяных компаний. По оценке министерства, с этой надбавкой бензин на их заправках к концу года подорожает на 11%, или на 7,1 рубля за литр, летний дизель на 10,7%, или на 8,2 рубля."},{"id":"b009","kind":"heading","text":"Почему нефтекомпании теряют деньги на импортном бензине?"},{"id":"b010","kind":"paragraph","text":"Своего бензина не хватает, и часть приходится ввозить. В сентябре импортный АИ-92 стоил 108 тыс. рублей за тонну, а российский на бирже 70,17 тыс. Демпфер покрывает часть разницы, но не наценку за санкционные риски и доставку по России. В итоге каждый литр импортного топлива приносит 13–18 рублей убытка."},{"id":"b011","kind":"heading","text":"Какой вариант дешевле для водителей?"},{"id":"b012","kind":"paragraph","text":"Второй вариант: включить в демпфер доставку топлива по железной дороге с Северо-Запада в центр. Тогда цены поднимут на 1,6 рубля за литр, но бюджет будет доплачивать нефтяникам до 2 млрд рублей в месяц. Минфин этот вариант не поддерживает."}],"sources":[{"label":"Стимулирование импорта бензина перекладывается на потребителя","url":"https://www.kommersant.ru/doc/9045149"},{"label":"Нефтекомпании могут повысить цены на АЗС на 2,1 рубля","url":"https://www.kommersant.ru/doc/9045179"},{"label":"Топливо привозного розлива","url":"https://kommersant.ru/doc/9027583"},{"label":"Цены на бензин в РФ снизились на 0,69%","url":"https://www.interfax.ru/business/1124061"},{"label":"Спрос не давит","url":"https://rg.ru/2026/10/22/spros-ne-davit.html"}],"sourceBodySha256":"9e2e55674eb7e77b6baeb4a6291922463595de9952c285600f9debb06446d035"}')}}]);